<style>
:root{
  --bg:#070506;--velvet:#1a0710;--burgundy:#3a0f1d;--navy:#07111f;
  --gold:#d6ad60;--soft:#f3d79b;--ivory:#f8efe2;--muted:#b9a999;
  --panel:rgba(255,244,220,.06);--border:rgba(214,173,96,.28);
  --serif:Georgia,"Times New Roman",serif;
  --sans:Inter,system-ui,"Segoe UI",sans-serif;
  --nav-h:72px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--nav-h) + 8px)}
body{background:var(--bg);color:var(--ivory);font-family:var(--sans);line-height:1.65;font-size:16px;overflow-x:hidden;-webkit-font-smoothing:antialiased}
body::before{content:"";position:fixed;inset:-50%;z-index:100;pointer-events:none;opacity:.07;
  background-image:repeating-radial-gradient(circle at 17% 32%,#fff 0 .5px,transparent .5px 3px),repeating-radial-gradient(circle at 83% 68%,#fff 0 .5px,transparent .5px 4px);mix-blend-mode:overlay}
img{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button,input,select{font:inherit;color:inherit}
ul{list-style:none}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.12;letter-spacing:-.01em}
:focus-visible{outline:2px solid var(--soft);outline-offset:3px;border-radius:4px}
.wrap{width:min(1200px,92%);margin-inline:auto}
section{position:relative;padding:clamp(72px,10vw,130px) 0}
.eyebrow{display:inline-flex;align-items:center;gap:12px;font-size:.75rem;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin-bottom:18px}
.eyebrow::before{content:"";width:40px;height:1px;background:var(--gold)}
.h2{font-size:clamp(2rem,5vw,3.6rem);margin-bottom:18px}
.lead{color:var(--muted);max-width:60ch;font-size:1.05rem}
.divider{height:1px;border:0;background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:.5}
.sec-head{margin-bottom:56px}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:14px 28px;border-radius:999px;border:1px solid var(--gold);background:transparent;color:var(--soft);font-size:.82rem;letter-spacing:.14em;text-transform:uppercase;cursor:pointer;transition:transform .3s,background .3s,color .3s,box-shadow .3s}
.btn:hover{background:rgba(214,173,96,.14);transform:translateY(-2px);box-shadow:0 10px 30px -10px rgba(214,173,96,.5)}
.btn:active{transform:translateY(0)}
.btn.primary{background:linear-gradient(135deg,var(--soft),var(--gold));color:#1a0710;font-weight:600;border-color:transparent}
.btn.primary:hover{background:linear-gradient(135deg,#fff0cc,var(--soft));box-shadow:0 12px 36px -8px rgba(243,215,155,.6)}
.btn.small{padding:10px 20px;font-size:.74rem}

/* Nav */
.nav{position:sticky;top:0;z-index:50;height:var(--nav-h);display:flex;align-items:center;transition:background .4s,border-color .4s,backdrop-filter .4s;border-bottom:1px solid transparent}
.nav.scrolled{background:rgba(7,5,6,.82);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-color:var(--border)}
.nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}
.logo{font-family:var(--serif);letter-spacing:.42em;font-size:1.1rem;color:var(--soft)}
.logo span{color:var(--gold)}
.nav-links{display:flex;gap:34px}
.nav-links a{font-size:.78rem;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);position:relative;padding:6px 0;transition:color .3s}
.nav-links a::after{content:"";position:absolute;left:0;bottom:0;height:1px;width:100%;background:var(--gold);transform:scaleX(0);transform-origin:left;transition:transform .35s}
.nav-links a:hover,.nav-links a.active{color:var(--soft)}
.nav-links a:hover::after,.nav-links a.active::after{transform:scaleX(1)}
.nav-right{display:flex;align-items:center;gap:14px}
.burger{display:none;width:44px;height:44px;border-radius:50%;border:1px solid var(--border);background:var(--panel);cursor:pointer;position:relative}
.burger i{position:absolute;left:12px;right:12px;height:1.5px;background:var(--soft);transition:.3s}
.burger i:nth-child(1){top:16px}.burger i:nth-child(2){top:21px}.burger i:nth-child(3){top:26px}
.burger[aria-expanded="true"] i:nth-child(1){top:21px;transform:rotate(45deg)}
.burger[aria-expanded="true"] i:nth-child(2){opacity:0}
.burger[aria-expanded="true"] i:nth-child(3){top:21px;transform:rotate(-45deg)}

/* Hero */
.hero{min-height:calc(100vh - var(--nav-h));margin-top:calc(var(--nav-h) * -1);padding:calc(var(--nav-h) + 60px) 0 80px;display:flex;align-items:center;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:0;z-index:-3;background:radial-gradient(ellipse at 70% 30%,var(--burgundy),var(--velvet) 50%,var(--navy))}
.hero-bg img{width:100%;height:100%;object-fit:cover;opacity:.55;animation:slowzoom 30s ease-in-out infinite alternate}
@keyframes slowzoom{from{transform:scale(1)}to{transform:scale(1.1)}}
.hero::before{content:"";position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,rgba(7,5,6,.75),rgba(7,5,6,.35) 40%,rgba(7,5,6,.95)),linear-gradient(90deg,rgba(7,5,6,.85),transparent 70%)}
.spot{position:absolute;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(30px)}
.spot.a{width:70vmax;height:70vmax;top:-40vmax;left:5%;background:radial-gradient(circle,rgba(243,215,155,.28),transparent 60%);animation:sway 12s ease-in-out infinite alternate}
.spot.b{width:50vmax;height:50vmax;top:-20vmax;right:-10vmax;background:radial-gradient(circle,rgba(214,173,96,.18),transparent 60%);animation:sway 16s ease-in-out infinite alternate-reverse}
@keyframes sway{from{transform:translateX(-4%)}to{transform:translateX(6%)}}
.hero-inner{max-width:900px}
.hero .event-name{font-size:.85rem;letter-spacing:.4em;text-transform:uppercase;color:var(--gold);margin-bottom:26px;display:flex;align-items:center;gap:16px}
.hero .event-name::before{content:"";width:56px;height:1px;background:var(--gold)}
.hero h1{font-size:clamp(3rem,9.5vw,8rem);line-height:.98;margin-bottom:30px;background:linear-gradient(180deg,var(--ivory) 30%,var(--soft) 70%,var(--gold));-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:none}
.hero h1 em{font-style:italic;display:block}
.hero p.sub{color:#d9cbb9;font-size:clamp(1rem,1.6vw,1.2rem);max-width:54ch;margin-bottom:36px}
.badges{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:38px}
.badge{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border:1px solid var(--border);border-radius:999px;background:rgba(7,5,6,.5);backdrop-filter:blur(8px);font-size:.82rem;color:var(--soft)}
.badge svg{width:14px;height:14px;stroke:var(--gold);fill:none;stroke-width:1.6}
.cta-row{display:flex;flex-wrap:wrap;gap:16px}
.scroll-hint{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);font-size:.65rem;letter-spacing:.35em;text-transform:uppercase;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:10px}
.scroll-hint::after{content:"";width:1px;height:38px;background:linear-gradient(var(--gold),transparent);animation:drip 2s infinite}
@keyframes drip{0%{transform:scaleY(0);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}51%{transform-origin:bottom}100%{transform:scaleY(0);transform-origin:bottom}}

/* Concept */
.concept{background:linear-gradient(180deg,var(--bg),var(--velvet) 60%,var(--bg))}
.concept-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:clamp(30px,6vw,90px);align-items:end;margin-bottom:64px}
.concept-grid p{color:var(--muted);font-size:1.08rem}
.concept-grid p:first-letter{font-family:var(--serif);font-size:4rem;float:left;line-height:.85;padding:6px 12px 0 0;color:var(--gold)}
.cards3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.glass{background:var(--panel);border:1px solid var(--border);border-radius:18px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);transition:transform .4s,border-color .4s,box-shadow .4s,background .4s}
.feature{padding:34px 30px}
.feature:hover{transform:translateY(-6px);border-color:var(--gold);box-shadow:0 24px 50px -24px rgba(214,173,96,.35);background:rgba(255,244,220,.09)}
.feature:nth-child(2){margin-top:32px}
.feature .ic{width:52px;height:52px;border-radius:50%;border:1px solid var(--gold);display:grid;place-items:center;margin-bottom:22px;background:radial-gradient(circle,rgba(214,173,96,.2),transparent)}
.feature .ic svg{width:24px;height:24px;stroke:var(--soft);fill:none;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.feature h3{font-size:1.5rem;margin-bottom:10px}
.feature p{color:var(--muted);font-size:.95rem}

/* Timeline */
.program{background:radial-gradient(ellipse at 10% 20%,rgba(58,15,29,.6),transparent 55%),radial-gradient(ellipse at 90% 80%,rgba(7,17,31,.9),transparent 60%),var(--bg)}
.timeline{position:relative;max-width:900px;margin-inline:auto}
.timeline::before{content:"";position:absolute;left:110px;top:0;bottom:0;width:1px;background:linear-gradient(transparent,var(--gold) 8%,var(--gold) 92%,transparent);opacity:.6}
.t-item{display:grid;grid-template-columns:110px 1fr;gap:0;position:relative;padding-bottom:30px}
.t-time{font-family:var(--serif);font-size:1.8rem;color:var(--soft);padding-right:34px;text-align:right;line-height:1.3}
.t-item::before{content:"";position:absolute;left:105px;top:14px;width:11px;height:11px;border-radius:50%;background:var(--bg);border:1px solid var(--gold);box-shadow:0 0 0 4px rgba(214,173,96,.12);transition:.3s;z-index:1}
.t-item:hover::before{background:var(--gold);box-shadow:0 0 18px var(--gold)}
.t-body{margin-left:36px;padding:22px 26px}
.t-body:hover{border-color:var(--gold);transform:translateX(6px)}
.t-body h3{font-size:1.4rem;margin-bottom:6px}
.t-body p{color:var(--muted);font-size:.95rem;margin-bottom:12px}
.tag{display:inline-block;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);border:1px solid var(--border);border-radius:999px;padding:4px 12px}

/* Artists */
.artists{background:linear-gradient(180deg,var(--bg),var(--navy) 50%,var(--bg))}
.artist-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.artist{overflow:hidden;display:flex;flex-direction:column}
.artist:nth-child(4n+2){margin-top:40px}
.artist:nth-child(4n+4){margin-top:20px}
.artist:nth-child(4n+3){margin-top:-10px}
.artist:hover{transform:translateY(-8px);border-color:var(--gold);box-shadow:0 30px 60px -30px rgba(214,173,96,.4)}
.a-img{aspect-ratio:4/3.4;overflow:hidden;background:linear-gradient(135deg,var(--burgundy),var(--navy));position:relative}
.a-img img{width:100%;height:100%;object-fit:cover;filter:grayscale(.4) contrast(1.05) brightness(.85);transition:transform .8s,filter .6s}
.artist:hover .a-img img{transform:scale(1.08);filter:grayscale(0) brightness(1)}
.a-img::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 50%,rgba(7,5,6,.85))}
.a-body{padding:20px 22px 24px;display:flex;flex-direction:column;flex:1;gap:4px}
.a-body h3{font-size:1.3rem}
.a-role{font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;color:var(--gold)}
.a-body p{color:var(--muted);font-size:.9rem;margin:8px 0 18px;flex:1}

/* Venue */
.venue-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:clamp(28px,5vw,70px);align-items:start}
.venue-info h3{font-size:2rem;color:var(--soft);margin-bottom:4px}
.address{color:var(--gold);margin-bottom:28px;font-size:.95rem}
.info-block{padding:20px 0;border-top:1px solid var(--border)}
.info-block h4{font-family:var(--sans);font-size:.75rem;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:8px}
.info-block p{color:var(--muted);font-size:.95rem}
.map{padding:14px;overflow:hidden}
.map svg{width:100%;height:auto;border-radius:10px;display:block}
.map figcaption{font-size:.75rem;color:var(--muted);padding:12px 6px 2px;letter-spacing:.06em}
.route{stroke-dasharray:6 7;animation:dash 1.6s linear infinite}
@keyframes dash{to{stroke-dashoffset:-26}}
.pulse{animation:pulse 2.4s ease-out infinite;transform-box:fill-box;transform-origin:center}
@keyframes pulse{0%{transform:scale(.6);opacity:.9}100%{transform:scale(2.4);opacity:0}}

/* Tickets */
.tickets{background:radial-gradient(ellipse at 50% 0%,rgba(58,15,29,.8),transparent 60%),var(--bg)}
.tier-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;align-items:stretch}
.tier{padding:40px 32px;position:relative;display:flex;flex-direction:column}
.tier:hover{transform:translateY(-10px);border-color:var(--soft);box-shadow:0 0 0 1px rgba(243,215,155,.3),0 40px 80px -30px rgba(214,173,96,.45);background:linear-gradient(180deg,rgba(214,173,96,.1),var(--panel))}
.tier.rec{background:linear-gradient(180deg,rgba(214,173,96,.13),rgba(58,15,29,.45));border-color:var(--gold);transform:translateY(-16px)}
.tier.rec:hover{transform:translateY(-26px)}
.rec-badge{position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,var(--soft),var(--gold));color:#1a0710;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;padding:6px 16px;border-radius:999px;white-space:nowrap}
.tier h3{font-size:1.7rem;margin-bottom:6px}
.price{font-family:var(--serif);font-size:3.4rem;color:var(--soft);line-height:1;margin:14px 0 6px}
.price small{font-family:var(--sans);font-size:.78rem;color:var(--muted);letter-spacing:.1em}
.tier ul{margin:26px 0 34px;flex:1;border-top:1px solid var(--border)}
.tier li{padding:12px 0 12px 30px;position:relative;color:var(--muted);font-size:.95rem;border-bottom:1px solid rgba(214,173,96,.1)}
.tier li::before{content:"";position:absolute;left:4px;top:19px;width:10px;height:5px;border-left:1.5px solid var(--gold);border-bottom:1.5px solid var(--gold);transform:rotate(-45deg)}
.tier .btn{width:100%}

/* FAQ */
.faq-list{max-width:820px;margin-inline:auto}
.faq-item{border-bottom:1px solid var(--border)}
.faq-item:first-child{border-top:1px solid var(--border)}
.faq-q{width:100%;background:none;border:0;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:20px;text-align:left;padding:26px 6px;font-family:var(--serif);font-size:1.3rem;transition:color .3s}
.faq-q:hover{color:var(--soft)}
.faq-q .pm{flex:none;width:30px;height:30px;border:1px solid var(--gold);border-radius:50%;position:relative;transition:transform .4s,background .3s}
.faq-q .pm::before,.faq-q .pm::after{content:"";position:absolute;left:50%;top:50%;width:11px;height:1.5px;background:var(--gold);transform:translate(-50%,-50%);transition:.3s}
.faq-q .pm::after{transform:translate(-50%,-50%) rotate(90deg)}
.faq-q[aria-expanded="true"] .pm{transform:rotate(180deg);background:rgba(214,173,96,.15)}
.faq-q[aria-expanded="true"] .pm::after{transform:translate(-50%,-50%) rotate(0)}
.faq-a{display:grid;grid-template-rows:0fr;transition:grid-template-rows .45s ease}
.faq-a.open{grid-template-rows:1fr}
.faq-a>div{overflow:hidden}
.faq-a p{color:var(--muted);padding:0 50px 26px 6px}

/* Newsletter */
.news{padding:clamp(60px,8vw,100px) 0}
.news-box{padding:clamp(34px,6vw,70px);text-align:center;background:radial-gradient(ellipse at 50% 0%,rgba(214,173,96,.16),transparent 65%),linear-gradient(135deg,var(--burgundy),var(--velvet) 60%,var(--navy));border:1px solid var(--border);border-radius:24px}
.news-box h2{font-size:clamp(1.8rem,4vw,2.8rem);margin-bottom:12px}
.news-box p{color:var(--muted);margin-bottom:28px}
.news-form{display:flex;gap:12px;max-width:560px;margin-inline:auto;flex-wrap:wrap;justify-content:center}
.field{flex:1 1 260px;text-align:left}
.input{width:100%;padding:14px 20px;background:rgba(7,5,6,.6);border:1px solid var(--border);border-radius:999px;outline:0;transition:border-color .3s,box-shadow .3s}
.input::placeholder{color:#7d7163}
.input:hover{border-color:rgba(214,173,96,.55)}
.input:focus{border-color:var(--soft);box-shadow:0 0 0 3px rgba(243,215,155,.18)}
.input[aria-invalid="true"]{border-color:#e0707f}
.err{display:block;min-height:1.3em;font-size:.78rem;color:#f09aa6;padding:5px 18px 0}

/* Footer */
footer{border-top:1px solid var(--border);padding:70px 0 34px;background:linear-gradient(180deg,var(--bg),var(--velvet))}
.foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px;margin-bottom:50px}
.foot-grid p,.foot-grid li{color:var(--muted);font-size:.9rem}
.foot-grid h4{font-family:var(--sans);font-size:.72rem;letter-spacing:.24em;text-transform:uppercase;color:var(--gold);margin-bottom:14px}
.foot-grid li{margin-bottom:6px}
.foot-grid a{transition:color .3s}
.foot-grid a:hover{color:var(--soft)}
.foot-grid .logo{display:inline-block;margin-bottom:14px}
.foot-bottom{border-top:1px solid var(--border);padding-top:26px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;font-size:.8rem;color:var(--muted)}
.foot-bottom em{color:var(--soft);font-style:normal}

/* Modal */
.modal{position:fixed;inset:0;z-index:200;display:grid;place-items:center;padding:20px;background:rgba(4,2,3,.82);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s}
.modal.open{opacity:1;visibility:visible}
.dialog{position:relative;width:min(860px,100%);max-height:92vh;overflow:auto;border-radius:22px;background:linear-gradient(145deg,#1f0a13,#0b0709 60%,#07111f);border:1px solid var(--border);box-shadow:0 50px 120px -20px #000;transform:translateY(24px) scale(.97);transition:transform .4s}
.modal.open .dialog{transform:none}
.dialog.narrow{width:min(520px,100%)}
.x{position:absolute;top:14px;right:14px;z-index:2;width:42px;height:42px;border-radius:50%;border:1px solid var(--border);background:rgba(7,5,6,.7);cursor:pointer;font-size:1.3rem;line-height:1;transition:.3s}
.x:hover{background:var(--gold);color:#1a0710;transform:rotate(90deg)}
.m-artist{display:grid;grid-template-columns:1fr 1.1fr}
.m-artist .m-img{min-height:320px;background:linear-gradient(135deg,var(--burgundy),var(--navy))}
.m-artist img{width:100%;height:100%;object-fit:cover}
.m-txt{padding:44px 38px}
.m-txt h3{font-size:2rem;margin:6px 0 14px}
.m-txt p{color:var(--muted);margin-bottom:20px}
.m-session{display:inline-flex;gap:8px;align-items:center;border:1px solid var(--border);border-radius:999px;padding:8px 16px;color:var(--soft);font-size:.85rem}
.m-ticket{padding:40px 34px 34px}
.m-ticket h3{font-size:1.9rem;margin-bottom:4px}
.m-ticket .mute{color:var(--muted);font-size:.9rem;margin-bottom:22px}
.form-row{margin-bottom:14px}
.form-row label{display:block;font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin-bottom:7px}
.m-ticket .input{border-radius:12px}
.m-ticket select.input{appearance:none;background-image:linear-gradient(45deg,transparent 50%,var(--gold) 50%),linear-gradient(135deg,var(--gold) 50%,transparent 50%);background-position:calc(100% - 22px) 52%,calc(100% - 16px) 52%;background-size:6px 6px;background-repeat:no-repeat}
.m-ticket select option{background:#1a0710}
.sel-tier{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border:1px solid var(--border);border-radius:12px;background:var(--panel);margin-bottom:14px}
.sel-tier strong{font-family:var(--serif);font-size:1.25rem;font-weight:400;color:var(--soft)}
.total{display:flex;justify-content:space-between;align-items:baseline;padding:16px 0;border-top:1px solid var(--border);margin-top:6px}
