/* ---------- Modals ---------- */
var lastFocus=null,activeModal=null;
var focusSel='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
function openModal(m){
  lastFocus=document.activeElement;activeModal=m;
  m.classList.add('open');m.setAttribute('aria-hidden','false');
  document.body.style.overflow='hidden';
  setTimeout(function(){var f=$('input,select',m)||$('.x',m);(f&&f.offsetParent?f:$('.x',m)).focus()},60);
}
function closeModal(){
  if(!activeModal)return;
  activeModal.classList.remove('open');activeModal.setAttribute('aria-hidden','true');
  activeModal=null;document.body.style.overflow='';
  if(lastFocus&&lastFocus.focus)lastFocus.focus();
}
$$('.modal').forEach(function(m){
  m.addEventListener('mousedown',function(e){if(e.target===m)closeModal()});
  m.addEventListener('click',function(e){if(e.target.closest('[data-close]'))closeModal()});
});
document.addEventListener('keydown',function(e){
  if(!activeModal)return;
  if(e.key==='Escape'){e.preventDefault();closeModal();return}
  if(e.key==='Tab'){
    var els=$$(focusSel,activeModal).filter(function(el){return el.offsetParent!==null});
    if(!els.length)return;
    var first=els[0],last=els[els.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  }
});

