function saveICS(){
  var stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  var lines=[
    'BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ARTIFACT//Museum Night//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',
    'BEGIN:VEVENT',
    'UID:artifact-museum-night-20261018@artifact.example',
    'DTSTAMP:'+stamp,
    'DTSTART:20261018T190000',
    'DTEND:20261019T020000',
    'SUMMARY:ARTIFACT: Museum Night',
    'LOCATION:The Old Gallery\\, Warsaw',
    'DESCRIPTION:A cinematic after-hours museum event with exhibitions\\, performances\\, talks\\, and guided tours.',
    'END:VEVENT','END:VCALENDAR'
  ];
  var blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');
  a.href=url;a.download='artifact-museum-night.ics';a.style.display='none';
  document.body.appendChild(a);a.click();
  setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},1000);
  toast('Calendar file downloaded — artifact-museum-night.ics');
}
$$('[data-ics]').forEach(function(b){b.addEventListener('click',saveICS)});
