function setMenu(open){
  links.classList.toggle('open',open);burger.setAttribute('aria-expanded',open?'true':'false');
}
burger.addEventListener('click',function(){setMenu(!links.classList.contains('open'))});
document.addEventListener('click',function(e){
  if(links.classList.contains('open')&&!e.target.closest('#nav'))setMenu(false);
});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!activeModal)setMenu(false)});
document.addEventListener('click',function(e){
  var a=e.target.closest('a[href^="#"]');if(!a||a.hasAttribute('data-soon'))return;
  var id=a.getAttribute('href');var t=id==='#top'?document.body:$(id);
  if(!t)return;
  e.preventDefault();
  var y=id==='#top'?0:t.getBoundingClientRect().top+window.scrollY-nav.offsetHeight+1;
  window.scrollTo({top:y,behavior:'smooth'});
  setMenu(false);
  if(history.replaceState)history.replaceState(null,'',id);
});
var secs=['program','artists','venue','tickets','faq'].map(function(id){return document.getElementById(id)});
var navA=$$('a',links);
function setActive(){
  var pos=window.scrollY+nav.offsetHeight+window.innerHeight*.3,cur=null;
  secs.forEach(function(s){if(s.offsetTop<=pos)cur=s.id});
  if(window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-4)cur='faq';
  navA.forEach(function(a){
    var on=a.getAttribute('href')==='#'+cur;
    a.classList.toggle('active',on);
    if(on)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');
  });
}
window.addEventListener('scroll',setActive,{passive:true});window.addEventListener('resize',setActive);setActive();

/* ---------- Scroll reveal ---------- */
var rev=$$('.reveal');
if('IntersectionObserver' in window){
  var io=new IntersectionObserver(function(es){
    es.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}});
  },{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  rev.forEach(function(r){io.observe(r)});
}else rev.forEach(function(r){r.classList.add('in')});
})();
